import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.Boholvbs.js";const c=JSON.parse('{"title":"订阅与余额","description":"","frontmatter":{},"headers":[],"relativePath":"guide/billing.md","filePath":"guide/billing.md","lastUpdated":1791785647000}'),l={name:"guide/billing.md"};function o(i,t,n,h,s,u){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="订阅与余额" tabindex="-1">订阅与余额 <a class="header-anchor" href="#订阅与余额" aria-label="Permalink to &quot;订阅与余额&quot;">​</a></h1><h2 id="订阅套餐" tabindex="-1">订阅套餐 <a class="header-anchor" href="#订阅套餐" aria-label="Permalink to &quot;订阅套餐&quot;">​</a></h2><p>档位照官方订阅划分，档与档之间的用量比例也照官方：</p><table tabindex="0"><thead><tr><th>平台</th><th>档位</th><th>对标官方</th><th>相对用量</th></tr></thead><tbody><tr><td>Claude</td><td>Claude Pro</td><td>Claude Pro</td><td>1×</td></tr><tr><td>Claude</td><td>Claude Max 5x</td><td>Claude Max 5x</td><td>5×</td></tr><tr><td>Claude</td><td>Claude Max 20x</td><td>Claude Max 20x</td><td>20×</td></tr><tr><td>OpenAI</td><td>Codex Plus</td><td>ChatGPT Plus</td><td>1×</td></tr><tr><td>OpenAI</td><td>Codex Pro</td><td>ChatGPT Pro</td><td>5×</td></tr></tbody></table><p>价格、有效期、每档的额度以控制台「购买订阅」页显示为准。</p><h3 id="额度怎么算" tabindex="-1">额度怎么算 <a class="header-anchor" href="#额度怎么算" aria-label="Permalink to &quot;额度怎么算&quot;">​</a></h3><ul><li>额度以<strong>美元</strong>计，每次请求按该模型的官方 API 标准价折算后扣减</li><li>每档有<strong>每日</strong>和<strong>每周</strong>两道上限，任一用完就暂停，到下一个周期自动恢复</li><li>订阅期内不扣账户余额</li></ul><p>所以同样的额度，用缓存命中率高、输出短的请求能用得更久。</p><h3 id="一个密钥只对应一档" tabindex="-1">一个密钥只对应一档 <a class="header-anchor" href="#一个密钥只对应一档" aria-label="Permalink to &quot;一个密钥只对应一档&quot;">​</a></h3><p>创建密钥时选的分组决定它走哪一档的额度。Claude 和 Codex 是不同的档，要各建一个密钥。</p><h2 id="余额" tabindex="-1">余额 <a class="header-anchor" href="#余额" aria-label="Permalink to &quot;余额&quot;">​</a></h2><p>余额按 token 实时扣费，用于按量计费的分组。可在「兑换」页用余额兑换码充值。</p><p>订阅和余额互不抵扣：用订阅档位的密钥不扣余额，余额也不能用来抵订阅额度。</p>',13)])])}const _=a(l,[["render",o]]);export{c as __pageData,_ as default};
